create table if not exists leads (id text primary key,name text not null default '',surname text not null default '',email text not null default '',whatsapp text not null default '',stage text not null default 'welcome',utm_source text not null default '',utm_medium text not null default '',utm_content text not null default '',test_generated boolean not null default false,test_username text,test_password text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists leads_test_whatsapp_unique on leads(whatsapp) where test_generated=true;